  async function prepareEmail(id){
    const invoice=findInvoice(id);
    if(!invoice)return;
    const c=consultantFor(invoice),eligibility=C.canEmail(invoice,c);
    if(!eligibility.ok){
      if(c&&c.active!==false&&c.notifications_enabled!==false&&!invoice.paid_at&&!invoice.cancelled_at&&!c.email)openConsultant(c.id);
      else if(!c&&!invoice.paid_at&&!invoice.cancelled_at)openEditor(id);
      toast(eligibility.error);
      return;
    }
    if(state.mode==='cloud')assertCloud();
    const subject=C.emailSubject(invoice),message=C.emailMessage(invoice,c),scope=accountScope(),client=cloud;
    dataRevision++;
    let opened=false;
    try{
      if(window.Native&&window.Native.openEmail)opened=!!window.Native.openEmail(c.email,subject,message);
      else{
        window.location.href='mailto:'+encodeURIComponent(c.email)+'?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(message);
        opened=true;
      }
    }catch(_){}
    const record={id:C.uuid(),workspace_id:state.mode==='cloud'?state.cloud.workspaceId:null,invoice_id:id,consultant_id:c.id,channel:'email',status:opened?'prepared':'failed',message,phone:c.email,created_at:new Date().toISOString(),confirmed_at:null,error:opened?null:'Não foi possível abrir o app de e-mail.'};
    pendingManual.set(record.id,{record,scope,client});
    await saveNotice(record,scope,client);
  }
  function openNotice(notice,error){
    const pending=pendingManual.get(notice.id),retry=!!pending;
    const isEmail=notice.channel==='email';
    const channelName=isEmail?'NOTIFICAÇÃO POR E-MAIL':'WHATSAPP MANUAL';
    const label=error?'Registro não salvo':notice.status==='failed'?(isEmail?'Não foi possível abrir o app de e-mail':'Não foi possível abrir o WhatsApp'):notice.status==='confirmed_by_user'?'Envio confirmado por você':'Mensagem preparada';
    openModal(channelName,label,'<p class="modal-intro">'+(error?'O contato foi tentado. Salve novamente o registro para manter o histórico.':notice.status==='failed'?(isEmail?'Confira se há aplicativo de e-mail instalado.':'Confira se o WhatsApp está instalado e se o telefone está correto.'):notice.status==='confirmed_by_user'?'Sua declaração de envio foi registrada.':'Confirme o envio no aplicativo. Ao voltar, declare abaixo se você enviou a mensagem.')+'</p>'+(error?'<div class="error-box">'+e(error)+'</div>':'')+'<p class="section-desc"><strong>'+(isEmail?'E-mail':'Telefone')+' do cadastro:</strong> '+e(notice.phone)+'</p><pre class="whatsapp-message">'+e(notice.message)+'</pre><div class="modal-actions"><button class="secondary" data-action="close">Fechar</button>'+(retry?'<button class="primary" data-action="notification-retry" data-id="'+e(notice.id)+'">Salvar registro novamente</button>':notice.status==='prepared'?'<button class="primary" data-action="notification-confirm" data-id="'+e(notice.id)+'">Confirmar que enviei</button>':'')+'</div>');
  }
  async function saveNotice(record,scope,client){try{let saved=record;if(state.mode==='cloud'){assertCloud();saved=await client.recordNotification(record);}if(scope!==accountScope()||client!==cloud)throw new Error('O espaço mudou. Volte à conta original para conferir o registro.');const previous=state;state={...state,notifications:state.notifications.filter(n=>n.id!==saved.id).concat(saved)};try{persist();}catch(error){state=previous;throw error;}pendingManual.delete(record.id);openNotice(saved);if(saved.status==='failed')toast(saved.channel==='email'?'Não foi possível abrir o app de e-mail.':'Não foi possível abrir o WhatsApp. A tentativa foi registrada.');}catch(error){pendingManual.set(record.id,{record,scope,client});openNotice(record,errorMessage(error));}}
  async function prepareWhatsApp(id){const invoice=findInvoice(id);if(!invoice)return;const c=consultantFor(invoice),eligibility=C.canWhatsApp(invoice,c);if(!eligibility.ok){if(c&&c.active!==false&&c.notifications_enabled!==false&&!invoice.paid_at&&!invoice.cancelled_at&&!C.normalizePhone(c.phone))openConsultant(c.id);else if(!c&&!invoice.paid_at&&!invoice.cancelled_at)openEditor(id);toast(eligibility.error);return;}if(state.mode==='cloud')assertCloud();const phone=C.normalizePhone(c.phone),message=C.whatsappMessage(invoice,c),scope=accountScope(),client=cloud,day=new Date().toISOString().slice(0,10),existing=state.notifications.find(n=>n.invoice_id===id&&n.consultant_id===c.id&&n.phone===phone&&n.message===message&&n.status!=='failed'&&String(n.created_at).slice(0,10)===day),pending=[...pendingManual.values()].find(p=>p.scope===scope&&p.record.invoice_id===id);if(pending){openNotice(pending.record,'O registro deste contato ainda precisa ser salvo.');return;}if(existing){openNotice(existing);return;}dataRevision++;let opened=false;try{if(window.Native)opened=!!(window.Native.openWhatsApp&&window.Native.openWhatsApp(phone,message));else{const target=window.open('about:blank','_blank');if(target){target.opener=null;target.location.href=C.whatsappUrl(phone,message);opened=true;}}}catch(_){}const record={id:C.uuid(),workspace_id:state.mode==='cloud'?state.cloud.workspaceId:null,invoice_id:id,consultant_id:c.id,channel:'whatsapp_manual',status:opened?'prepared':'failed',message,phone,created_at:new Date().toISOString(),confirmed_at:null,error:opened?null:'Não foi possível abrir o WhatsApp.'};pendingManual.set(record.id,{record,scope,client});await saveNotice(record,scope,client);}
