  function compactRow(invoice,index) { const late=C.status(invoice)==='overdue';return '<div class="row"><button class="row-open" data-action="detail" data-id="'+e(invoice.id)+'"><span class="client-avatar '+(late?'rose':['mint','lilac',''][index%3])+'">'+e(initials(invoice.client_name))+'</span><span class="row-copy"><span class="row-title" style="display:block">'+e(invoice.client_name)+'</span><span class="row-sub" style="display:block">NF '+e(invoice.nf_number)+'</span></span><span class="row-end"><span class="row-date" style="display:block">'+e(dateLabel(C.dueDate(invoice)))+'</span><span class="row-status '+(late?'red':'')+'" style="display:block">'+e(relative(invoice))+'</span></span></button></div>'; }
