    const totals=scoped.reduce((sum,i)=>{if(Number.isInteger(i.amount_cents)){sum.total+=i.amount_cents;if(C.status(i)==='paid')sum.paid+=i.amount_cents;else if(C.status(i)!=='cancelled'){sum.unpaid+=i.amount_cents;if(C.status(i)==='overdue')sum.overdue+=i.amount_cents;}}else sum.missing++;return sum;},{total:0,paid:0,unpaid:0,overdue:0,missing:0});
