    const metric=(cls,label,value,ico,foot)=>'<div class="metric '+cls+'"><div class="metric-label">'+label+icon(ico)+'</div><div class="metric-value">'+value+'</div><div class="metric-foot"><span class="dot"></span>'+foot+'</div></div>';
