      'Distribuidora Salvador Alimentos,2026-11-01,NF-1050,Fabio Araujo,fabio.araujo@empresa.com.br,+5571999887766,24600.00,Banco,Itaú\n'+
      'Tecnologia Alpha Ltda,2026-11-04,NF-1051,Thiago Nogueira,thiago.nogueira@empresa.com.br,+5571988112233,4890.00,Recursos Próprios,\n'+
      'Construtora Salvador Nobre,2026-10-10,NF-1052,Bartolomeu Gonçalves,bartolomeu@empresa.com.br,+5571977665544,32100.00,Banco,Bradesco';
